import { useEffect } from "react";
import * as Cesium from "cesium";

// The reference map's tracked-caps country names (`.place` in slate.css,
// copied verbatim: 24 px, .3em tracking) over the live satellite basemap.
// countryLabels.json is generated by countryLabels.gen.py from Natural Earth
// 1:50m admin-0 (public domain): per country its LABELRANK, NE's own label
// point, and one interior point per 1 degree cell, in eighth degrees. A country is named at the
// interior point nearest the middle of its on-screen part, so a regional view
// still names the countries in it (the reference's OMAN on Musandam).

type Row = [string, number, number[], string];

/** Highest LABELRANK drawn at a camera height (m). */
export function maxRankAt(heightM: number): number {
  if (heightM < 2_500_000) return 10;
  if (heightM < 7_000_000) return 4;
  return 2;
}

/** Of a country's on-screen candidates, the one nearest their mean. */
export function pickLabel(
  pts: ReadonlyArray<{ x: number; y: number }>,
): { x: number; y: number } | null {
  if (!pts.length) return null;
  const mx = pts.reduce((a, p) => a + p.x, 0) / pts.length;
  const my = pts.reduce((a, p) => a + p.y, 0) / pts.length;
  let best = pts[0]!;
  let bd = Infinity;
  for (const p of pts) {
    const d = (p.x - mx) ** 2 + (p.y - my) ** 2;
    if (d < bd) {
      bd = d;
      best = p;
    }
  }
  return best;
}

/** Camera distance (m) past which a country of this LABELRANK is hidden; the
 *  same tiers as maxRankAt, expressed for Cesium's distanceDisplayCondition. */
export function farFor(rank: number): number {
  if (rank <= maxRankAt(Infinity)) return Number.POSITIVE_INFINITY;
  if (rank <= maxRankAt(2_500_000 + 1)) return 7_000_000;
  return 2_500_000;
}

/** The copy's letter-spaced place names, drawn as map labels so they move
 *  with the globe (an HTML overlay re-placed from the camera lagged and slid
 *  during a pan). Each country is pinned to one fixed point. */
export function SlatePlaces({
  viewer,
}: {
  viewer: Cesium.Viewer | null;
}): null {
  useEffect(() => {
    if (!viewer || viewer.isDestroyed()) return;
    const ds = new Cesium.CustomDataSource("__slate_places");
    const added = viewer.dataSources.add(ds);
    let live = true;
    void import("./countryLabels.json").then((mod) => {
      if (!live || viewer.isDestroyed()) return;
      const fill = Cesium.Color.fromCssColorString("rgba(230,236,240,.86)");
      const shadow = Cesium.Color.BLACK.withAlpha(0.65);
      for (const [t, rank, flat] of mod.default as unknown as Row[]) {
        const pts: { x: number; y: number }[] = [];
        for (let i = 0; i + 1 < flat.length; i += 2)
          pts.push({ x: flat[i]! / 8, y: flat[i + 1]! / 8 });
        const at = pickLabel(pts);
        if (!at) continue;
        ds.entities.add({
          position: Cesium.Cartesian3.fromDegrees(at.x, at.y),
          label: {
            text: t.toUpperCase().split("").join(" "),
            font: '600 24px "Source Sans 3", "Segoe UI", sans-serif',
            fillColor: fill,
            outlineColor: shadow,
            outlineWidth: 3,
            style: Cesium.LabelStyle.FILL_AND_OUTLINE,
            horizontalOrigin: Cesium.HorizontalOrigin.CENTER,
            verticalOrigin: Cesium.VerticalOrigin.CENTER,
            distanceDisplayCondition: new Cesium.DistanceDisplayCondition(
              0,
              farFor(rank),
            ),
          },
        });
      }
      viewer.scene.requestRender();
    });
    return () => {
      live = false;
      void added.then(() => {
        if (!viewer.isDestroyed()) viewer.dataSources.remove(ds, true);
      });
    };
  }, [viewer]);
  return null;
}
